      destOpts: [
        { key: 'email', label: 'Email', hint: S.apiUser?.email || 'Add an email in Rider Profile', planCls: 'p-good', planLbl: 'Configured route' },
      ].map(d => ({ ...d, cls: S.dest[d.key] ? 'on' : '', toggle: () => this.setState(p => ({ dest: { ...p.dest, [d.key]: !p.dest[d.key] } })) })),

      // ══════════ NEW SCREENS ══════════
      isConn: S.screen === 'conn', isSportP: S.screen === 'sportp', isFcSrc: S.screen === 'fcsrc',
      goFcSrc: this.go('fcsrc'),
