      noAddableSports: ADDABLE_SPORTS.length === 0,
      editingSportProfile: Boolean(S.sportProfileEditId),
      sportProfileModalKicker: S.sportProfileEditId ? 'Edit sport profile' : 'New sport profile',
      sportProfileModalTitle: S.sportProfileEditId ? `Edit ${sportLabel(S.newSport)}` : 'Add a sport',
      sportProfileSaveLabel: S.sportProfileEditId ? 'Save profile' : 'Add sport',
      canChooseSport: !S.sportProfileEditId,
      newSportName: sportLabel(S.newSport),
      newSportIsWave: ['surfing', 'sup'].includes(S.newSport),
      newSportIsWind: Boolean(S.newSport) && !['surfing', 'sup'].includes(S.newSport),
      nsMin: S.nsMin, nsMax: S.nsMax,
      nsMinUp: () => this.setState(p => ({ nsMin: Math.min(p.nsMax - 1, p.nsMin + 1) })),
      nsMinDown: () => this.setState(p => ({ nsMin: Math.max(2, p.nsMin - 1) })),
      nsMaxUp: () => this.setState(p => ({ nsMax: Math.min(30, p.nsMax + 1) })),
      nsMaxDown: () => this.setState(p => ({ nsMax: Math.max(p.nsMin + 1, p.nsMax - 1) })),
      nsWaveMin: S.nsWaveMin, nsWaveMax: S.nsWaveMax, nsPeriod: S.nsPeriod,
      nsWaveMinUp: () => this.setState(p => ({ nsWaveMin: Math.min(p.nsWaveMax - 0.1, +(p.nsWaveMin + 0.1).toFixed(1)) })),
      nsWaveMinDown: () => this.setState(p => ({ nsWaveMin: Math.max(0.1, +(p.nsWaveMin - 0.1).toFixed(1)) })),
      nsWaveMaxUp: () => this.setState(p => ({ nsWaveMax: Math.min(10, +(p.nsWaveMax + 0.1).toFixed(1)) })),
      nsWaveMaxDown: () => this.setState(p => ({ nsWaveMax: Math.max(p.nsWaveMin + 0.1, +(p.nsWaveMax - 0.1).toFixed(1)) })),
      nsPeriodUp: () => this.setState(p => ({ nsPeriod: Math.min(25, p.nsPeriod + 1) })),
